// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool doRevert) public {
        amount = bound(amount, 0, 1 ether);

        ReverterOrAcceptor helper = new ReverterOrAcceptor(doRevert);

        address payer = address(0xBEEF);
        vm.deal(payer, 2 ether);
        vm.prank(payer);
        (bool sent, ) = payable(address(c)).call{value: 1 ether}('');
        require(sent);

        vm.deal(address(this), 0);

        bool ok;
        try c.sendMoney(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract ReverterOrAcceptor {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    fallback() external payable {
        if (shouldRevert) revert("revert on fallback");
    }
}
